import React, { useState, useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';
import io from 'socket.io-client';

const socket = io('http://127.0.0.1:5000');


const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0002; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const interpolatePosition = (start, end, fraction) => {
  return {
    lat: start.lat + (end.lat - start.lat) * fraction,
    lng: start.lng + (end.lng - start.lng) * fraction
  };
};

const animateVehicle = (start, end, duration, updatePosition) => {
  const startTime = performance.now();

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const fraction = Math.min(elapsed / duration, 1);
    const position = interpolatePosition(start, end, fraction);

    updatePosition(position);

    if (fraction < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
};

const MapComponent = React.memo(({ vehicles, stations, step, onMapClick }) => {
  const [vehiclePositions, setVehiclePositions] = useState([]);


  useEffect(() => {
    for (vehicle in vehicles) {
      if (vehicle.id === step.vehicle_id){
        setVehiclePo
      }
    }

    if (vehicles && vehicles.length) {
      const updatedPositions = vehicles.map(vehicle => vehicle.location || { lat: 0, lng: 0 });
      setVehiclePositions(updatedPositions);
    }
  }, [vehicles]);
  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle, index) => {
        const position = [0, 0];
        if (vehicle) {
          const offset = getOffset(index);
          if (vehicle.location) {
            position[0] = vehicle.location.lat + offset.lat;
            position[1] = vehicle.location.lng + offset.lng;
          } else {
            // Utilisez une valeur par défaut si `vehicle.location` est `undefined`
            position[0] = vehiclePositions.lat + offset.lat;
            position[1] = vehiclePositions.lng + offset.lng;
            console.log("vehicle id", vehicle);
          }
        } else {
          console.log("Undefined vehicle detected.");
        }
        return (
          <Marker key={vehicle.id} position={position} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [station.location.lat + offset.lat, station.location.lng + offset.lng];
        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
    </MapContainer>
  );
});

export default MapComponent;
